def main():
    spec=load(ROOT/"config/semantic-search/kdi_semantic_search_spec_v1.json");manifest=load(ROOT/"config/semantic-search/kdi_semantic_pilot_v1.json");config=load(ROOT/"config/semantic-search/kdi_gold_pilot_v1.json")
