        expected=asset["content_fingerprint"]["value"];fingerprints=[expected,(p3 or p4)["source_fingerprint"],p5["analysis_run"]["source_fingerprint"],p7["source_fingerprint"],p8["source_fingerprint"],p9["source_fingerprint"]]+([p6["source_fingerprint"]] if p6 else [])
        if len(set(fingerprints))!=1:raise RuntimeError(f"EVIDENCE_SOURCE_MISMATCH:{asset['filename']}")
        packet={"review_packet_version":"kdi_human_gold_review_packet_v1","gold_standard_version":config["gold_standard_version"],"semantic_spec_version":"semantic_index_v1","semantic_spec_fingerprint":SPEC_FP,"pilot_manifest_version":manifest["manifest_version"],"asset_id":aid,"filename":asset["filename"],"media_type":asset["media_type"],"source_fingerprint":expected,"review_status":"AWAITING_HUMAN_REVIEW","reviewer_label":config["reviewer_label_default"],"explicit_signoff":False,"signed_off_at":None,"revision":0,"media":{"preview_url":f"/api/dev/library/media/{aid}/preview","duration":p3["technical_metadata"]["duration_seconds"] if video else None,"dimensions":p3["technical_metadata"].get("resolution") if video else p4.get("technical_metadata",{}).get("analysis_dimensions")},"layer_decisions":[empty_decision(aid,x) for x in p5["layers"]],"temporal_review":{"human_decision":None,"ai_scenes":p3["scene_candidates"] if video else [],"ai_events":p3["event_candidates"] if video else [],"scene_overrides":[],"event_overrides":[],"history":[]},"transcript_review":{"human_decision":None if video else "NOT_APPLICABLE","ai_audio":p6["layer_14"] if video else None,"chunks":p6["transcript_chunks"] if video else [],"overrides":[],"history":[]},"ocr_review":{"human_decision":None,"ai_layer_15":p7["layer_15"],"observations":p7["ocr_observations"],"overrides":[],"history":[]},"narrative_review":{"human_decision":None,"asset_narrative":p8["asset_narrative"],"search_summary":p8["search_summary"],"search_safe_narrative":p8["search_safe_narrative"],"scene_narratives":p8["scene_narratives"],"event_narratives":p8["event_narratives"],"overrides":[],"history":[]},"critical_issue_decisions":[{**x,"human_decision":None,"human_value":None,"reason":None,"reviewer_label":None,"reviewed_at":None,"history":[]} for x in p9["issues"] if x["priority"] in {"P0","P1"}],"phase9":{"overall_state":p9["overall_consistency_state"],"rules":p9["rule_results"],"all_issues":p9["issues"]},"review_requirements":{"layer_decisions_required":18,"p0_p1_resolution_required":True,"video_temporal_review_required":video,"transcript_review_required":video,"ocr_review_required":True,"narrative_review_required":True,"explicit_signoff_required":True},"history":[],"created_at":datetime.now(timezone.utc).isoformat(),"prohibitions":{"codex_human_approval":False,"production_writes":False,"database_migrations":False,"source_artifacts_modified":False}}
